        function SetfontSize(pOption) {
            if (pOption != "1" && pOption != "2" && pOption != "3" && pOption != "4") return;
            document.cookie = "fontSize=" + pOption + "; domain=ohmynews.com; path=/; Secure";
            if (typeof ohmyapp_setFontSize === 'function') ohmyapp_setFontSize(pOption);
            fontReSize(pOption);
