        function fontReSize(pFontSize, pObj) {
            if (pFontSize != "1" && pFontSize != "2" && pFontSize != "3" && pFontSize != "4") return;
            $(".font_level").find("button").removeClass("on");

            // 2023.09.05
            //본문 >> 1=14px / 2=16px / 3= 18px / 4=20px 
            // 덧붙이는글 >> 1번= 12px / 2번=14px / 3번=16px(디자인기본값) / 4번= 18px
            switch (pFontSize) {
                case "1":
                    $(".article_body").css("font-size", "14px"); //"1.4rem");
                    $(".article_body").find(".desc").css("font-size", "1.1rem");
                    $(".high_list").find("li").css("font-size", "1.1rem");
                    $(".editor_text, td[id='BoxTr'], td[id='BoxTd']").css("font-size", "1.2rem");
                    $(".add-comment").css("font-size", "12px"); // ".7em");
                    $("#btnFont1").addClass("on");
                    break;
                case "2":
                    $(".article_body").css("font-size", "16px"); // "1.6rem");
                    $(".article_body").find(".desc").css("font-size", "1.1rem");

                    $(".high_list").find("li").css("font-size", "1.3rem");
                    $(".editor_text, td[id='BoxTr'], td[id='BoxTd']").css("font-size", "1.4rem");
                    $(".add-comment").css("font-size", "14px"); //".9em");
                    $("#btnFont2").addClass("on");
                    break;
                case "3":
                    $(".article_body").css("font-size", "18px"); //"1.8rem");
                    $(".article_body").find(".desc").css("font-size", "1.3rem");
                    $(".high_list").find("li").css("font-size", "1.5rem");
                    $(".editor_text, td[id='BoxTr'], td[id='BoxTd']").css("font-size", "1.6rem");
                    $(".add-comment").css("font-size", "16px"); //"1.1em");
                    $("#btnFont3").addClass("on");
                    break;
                case "4":
                    $(".article_body").css("font-size", "20px"); //"2.0rem");
                    $(".article_body").find(".desc").css("font-size", "1.5rem");
                    $(".high_list").find("li").css("font-size", "1.7rem");
                    $(".editor_text, td[id='BoxTr'], td[id='BoxTd']").css("font-size", "1.8rem");
                    $(".add-comment").css("font-size", "18px"); //"1.3em");            
                    $("#btnFont4").addClass("on");
                    break;
            }
        }

